// Verifies a call from CommerceOS. Two layers:
// 1. Header Auth on the webhook trigger (X-CommerceOS-Token, credential "CommerceOS Webhook Token"): n8n answers 403
//    before this node runs unless the token matches. Works on every n8n plan (no Variables needed).
// 2. HMAC, OPTIONAL: enforced only when COMMERCEOS_N8N_WEBHOOK_SECRET is configured (an n8n Variable, or the environment
//    on self-hosted n8n with N8N_BLOCK_ENV_ACCESS_IN_NODE=false and NODE_FUNCTION_ALLOW_BUILTIN=crypto). Then the call must
//    carry X-CommerceOS-Timestamp (unix seconds, at most 5 minutes old) and
//    X-CommerceOS-Signature: v1=<hex HMAC-SHA256(secret, "<timestamp>.<raw body>")>, and Raw Body must be on the trigger.
// With no secret configured, the token alone authenticates the call and the parsed body is used.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
let secret;
try {
  secret = $vars.COMMERCEOS_N8N_WEBHOOK_SECRET;
} catch (e) {
  secret = undefined; // Variables are not available on this plan
}
if (!secret) {
  try {
    secret = $env.COMMERCEOS_N8N_WEBHOOK_SECRET;
  } catch (e) {
    secret = undefined; // n8n Cloud refuses $env
  }
}
let reason = null;
let body = null;
if (secret) {
  let raw = null;
  if (!item.binary || !item.binary.data) reason = 'no raw body (enable Raw Body on the trigger)';
  else raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  const ts = String(headers['x-commerceos-timestamp'] || '');
  const given = String(headers['x-commerceos-signature'] || '');
  if (!reason && !/^\d{9,11}$/.test(ts)) reason = 'missing or malformed timestamp';
  if (!reason && Math.abs(Date.now() / 1000 - Number(ts)) > 300) reason = 'timestamp too old or in the future';
  if (!reason) {
    const expected = 'v1=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
    const a = Buffer.from(given);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) reason = 'signature does not match';
  }
  if (!reason) {
    try {
      body = JSON.parse(raw);
    } catch (e) {
      reason = 'body is not JSON';
    }
  }
} else {
  body = item.json.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      body = null;
    }
  }
  if (!body || typeof body !== 'object') reason = 'body is not JSON';
}
return [{ json: { headers, body: reason ? null : body, signature_verified: !reason, signature_error: reason } }];

// 1. Authoritative Validation of Standard CommerceOS Event Envelope
const input = $input.first().json;
const body = input.body || input;
const event = body.event || body;

if (!event || typeof event !== 'object') {
  throw new Error('VALIDATION_ERROR: Missing event payload');
}

// Non-negotiable envelope attributes check
const requiredFields = ['id', 'type', 'version', 'tenant_id', 'aggregate_id', 'payload'];
for (const field of requiredFields) {
  if (!event[field]) {
    throw new Error(`VALIDATION_ERROR: Missing required event field '${field}'`);
  }
}

if (event.type !== 'order.created') {
  throw new Error(`VALIDATION_ERROR: Unsupported event type '${event.type}', expected 'order.created'`);
}

return [{
  json: {
    valid: true,
    event_id: event.id,
    event_type: event.type,
    event_version: event.version,
    tenant_id: event.tenant_id,
    aggregate_id: event.aggregate_id,
    actor_id: event.actor_id || 'system',
    correlation_id: event.correlation_id || event.aggregate_id,
    causation_id: event.id,
    timestamp: event.timestamp || new Date().toISOString(),
    payload: event.payload || {}
  }
}];

// Builds the notification request for CommerceOS (FX-99 Part A contract). The recipient is the order's customer,
// resolved by CommerceOS from order_id in this workspace: n8n never sends phone numbers.
const v = $input.first().json;
const orderId = v.aggregate_id;
if (!orderId) throw new Error('VALIDATION_ERROR: order.created has no aggregate_id');
return [{
  json: {
    correlation_id: v.correlation_id,
    causation_id: v.causation_id,
    idempotency_key: `n8n_ord_notif_${v.event_id}`,
    notification_payload: { channel: 'SMS', template_code: 'ORDER_CONFIRMATION', order_id: orderId }
  }
}];

// CommerceOS answers (FX-99 Part A): 2xx = sent; 424 INTEGRATION_NOT_CONFIGURED = nothing was sent (expected until
// automation sending exists); anything else, or no answer, is a failure.
const r = $input.first().json;
const status = Number(r.statusCode || 0);
const body = r.body && typeof r.body === 'object' ? r.body : {};
const code = (body.error && body.error.code) || (r.error ? 'N8N_CALL_ERROR' : null);
let outcome = 'FAILED';
if (status >= 200 && status < 300) outcome = 'SENT';
else if (status === 424) outcome = 'NOT_SENT';
return [{ json: { outcome, http_status: status || null, error_code: code, data: body.data ?? null } }];
